function transition(step,user=''){if(user)state.messages=addMessage(state.messages,'user',user);state.step=step;state.user='';state.draft='';state.overlay=null;const {body}=answer();state.messages=addMessage(state.messages,'assistant',body,step);state.mode='chat';moveChat=true;newReply=true;render();}
function phase(){updateStage();}
function bars(values,labels,highlight=-1){const peak=Math.max(...values,1),max=Math.ceil(peak/(peak>10000?10000:1000))*(peak>10000?10000:1000);return `<svg class="chart-svg" viewBox="0 0 354 178" role="img" aria-label="${values.map((v,i)=>labels[i]+': '+money(v)).join('; ')}">${[0,.5,1].map(f=>`<path class="gridline" d="M0 ${142-f*125}H302"/><text x="308" y="${146-f*125}">${Math.round(max*f).toLocaleString('ru-RU')}</text>`).join('')}${values.map((v,i)=>{const x=12+i*290/values.length,h=v/max*125;return `<rect class="bar ${highlight===i?'selected':''}" x="${x}" y="${142-h}" width="${Math.min(25,180/values.length)}" height="${h}" rx="4"/><text x="${x-4}" y="164" class="axis-label">${labels[i]}</text>`;}).join('')}</svg>`;}
function chartIcon(name){if(/Техник|компьютер/.test(name))return '<rect x="-7" y="-6" width="14" height="10" rx="1.5"/><path d="M0 4v4m-4 0h8"/>';if(/Процент/.test(name))return '<path d="m-5 5 10-10"/><circle cx="-3.5" cy="-3.5" r="1.5"/><circle cx="3.5" cy="3.5" r="1.5"/>';if(/Перевод|Зарплат/.test(name))return '<path fill="white" stroke="none" d="M-8-5H1V-9L8-2 1 5V1H-8ZM8 5H-1V9L-8 2-1-5V-1H8Z"/>';if(/Кафе/.test(name))return '<path d="M-6-7v6m3-6v6m-6-6v6q0 3 3 3v5M5-7v14M5-7q-5 4 0 7"/>';if(/Супермаркет/.test(name))return '<path d="m-7-2 3 8h8l3-8Zm2 0 3-5m7 5-3-5M-2-1v5m4-5v5"/>';if(/часть|Возврат/.test(name))return '<circle cx="0" cy="-4" r="3"/><path d="M-6 7v-1a6 6 0 0 1 12 0v1"/>';return '<circle cx="-6" cy="0" r=".8" fill="white"/><circle cx="0" cy="0" r=".8" fill="white"/><circle cx="6" cy="0" r=".8" fill="white"/>';}
