function startIntro(){reset();state.mode='intro';state.page='home';$('#landing').hidden=true;$('#prototype').hidden=false;window.scrollTo({top:0,behavior:'instant'});render();playback=new Playback({duration:3800,steps:INTRO_STEPS.filter(step=>step.page!=='bank'),onStep:step=>{if(step.page){state.page=step.page;render();}if(step.action==='tap-home')showTouch('.operations-entry');if(step.action==='tap-expenses')showTouch('[data-action="open-expenses"]');},onFrame:(_,time)=>{state.clock=time;$('#playback-progress').style.transform=`scaleX(${time/INTRO_DURATION})`;$('#playback-time').textContent=`${(time/1000).toFixed(1)} / ${(INTRO_DURATION/1000).toFixed(1)} с`;$('#playback-panel [role="progressbar"]').setAttribute('aria-valuenow',String(Math.round(time/INTRO_DURATION*100)));},onEnd:()=>startReveal(true)});playback.play();updateStage();}
async function dismissTaya(){if(state.dismissing)return;const current=state;state.dismissing=true;app.inert=true;const source=app.querySelector('.taya-reveal .taya-avatar'),target=app.querySelector('.bank-nav button:nth-child(4) img'),offer=app.querySelector('.taya-reveal');
 try{if(source&&target&&!reducedMotion()){const root=app.getBoundingClientRect(),scale=root.width/app.offsetWidth,s=source.getBoundingClientRect(),t=target.getBoundingClientRect();const sx=(s.left+s.width/2-root.left)/scale-30,sy=(s.top+s.height/2-root.top)/scale-30,tx=(t.left+t.width/2-root.left)/scale-30,ty=(t.top+t.height/2-root.top)/scale-30;
 const flyer=document.createElement('div');flyer.className='taya-flyer';flyer.innerHTML=tayaVector();app.append(flyer);source.style.visibility='hidden';
 const move=(x,y,size,opacity=1)=>({transform:`translate(${x}px,${y}px) scale(${size})`,opacity});
 const flight=flyer.animate([{...move(sx,sy,1),offset:0},{...move(sx+8,sy-9,.9),offset:.12},{...move(sx+(tx-sx)*.65,sy+(ty-sy)*.35-22,.65),offset:.36},{...move(tx,ty-55,.5),offset:.63},{...move(tx,ty-59,.5),offset:.75},{...move(tx,ty+2,.2),offset:.9},{...move(tx,ty+7,0,0),offset:1}],{duration:1100,easing:'cubic-bezier(.25,.65,.3,1)',fill:'both'});
 const fades=[...app.querySelectorAll('.taya-speech,.taya-actions')].map(n=>n.animate([{opacity:1},{opacity:0}],{duration:160,fill:'forwards'}));
 const collapse=offer.animate([{height:offer.offsetHeight+'px',marginBottom:'8px'},{height:'0px',marginBottom:'0px'}],{duration:400,delay:300,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});
 const splash=target.animate([{transform:'scale(1)'},{transform:'translateY(3px) scale(1.22,.72)',offset:.28},{transform:'translateY(-2px) scale(.9,1.12)',offset:.58},{transform:'scale(1.04,.97)',offset:.82},{transform:'scale(1)'}],{duration:440,delay:920,easing:'ease-out'});
 try{await Promise.all([flight.finished,splash.finished]);}finally{flyer.remove();for(const a of [flight,splash,collapse,...fades])a.cancel();}}
 }finally{if(state===current){state.offer=false;state.offerDismissed=true;state.tayaInChats=true;state.minimized=false;state.dismissing=false;render();}}
}
const sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function playRequest(scenario){state.scenario=scenario;if(scenario==='computer'){state.personal=initialPersonal();state.exclude=true;state.reportPeriod='Ноябрь';}if(scenario==='salary'){state.payroll=initialSalary();state.expected=100700;state.expectedSet=false;state.selectedSalary=new Set(salary.map(x=>x.id));}if(scenario==='friends'){state.shared=initialShared();state.selectedRefunds=new Set();}state.messages=addMessage([],'assistant',(()=>{state.step='welcome';return answer().body;})(),'welcome');state.chatScroll=0;state.mode='typing';state.page='chat';state.step='welcome';state.draft='';state.keyboard=false;state.overlay=null;render();syncPicker();window.scrollTo({top:0,behavior:reducedMotion()?'instant':'smooth'});return animateRequest(cleanRequest(queries[scenario]));}
async function animateRequest(request){const generation=++typingGeneration;state.mode='typing';state.draft='';state.keyboard=false;state.overlay=null;render();await sleep(450);if(generation!==typingGeneration)return;state.keyboard=true;render();showTouch('.composer textarea');await sleep(420);if(generation!==typingGeneration)return;for(const letter of request){if(generation!==typingGeneration)return;state.draft+=letter;const field=$('#message');if(!field)return;field.value=state.draft;field.style.height='26px';field.style.height=Math.min(88,field.scrollHeight)+'px';app.querySelector('.send-button').disabled=false;app.querySelector('.key.pressed')?.classList.remove('pressed');const key=[...app.querySelectorAll('[data-key]')].find(k=>k.dataset.key===letter.toLowerCase());key?.classList.add('pressed');await sleep(reducedMotion()?1:letter===' '?65:/[,;:]/.test(letter)?170:44);}app.querySelector('.key.pressed')?.classList.remove('pressed');await sleep(550);if(generation!==typingGeneration)return;showTouch('.send-button');await sleep(250);if(generation!==typingGeneration)return;const panel=app.querySelector('.russian-keyboard');if(panel&&!reducedMotion())await panel.animate([{transform:'translateY(0)'},{transform:'translateY(100%)'}],{duration:260,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}).finished.catch(()=>{});if(generation!==typingGeneration)return;state.mode='chat';state.keyboard=false;send();}
function minimizeChat(){state.chatScroll=app.querySelector('.chat-scroll')?.scrollTop||state.chatScroll;state.returnMode=state.mode;state.mode='await-taya';state.page='bank';state.minimized=true;state.offer=false;state.keyboard=false;state.overlay=null;typingGeneration++;render();}
function playReimbursement(){if(state.scenario!=='salary'||state.step!=='salary-summary'||state.mode!=='chat'||state.overlay)return;return animateRequest(typo('6700 за возврат билета в командировку 30.09'));}

function chooseTask(){state.mode='choose';state.page='chat';state.minimized=false;render();syncPicker();}
function finish(){if(state.scenario)completedScenarios.add(state.scenario);state.mode='choose';state.page='chat';render();syncPicker();}
app.addEventListener('click',async ev=>{const el=ev.target.closest('[data-action]');if(!el||el.disabled||['intro','typing'].includes(state.mode))return;pressFeedback(el);const a=el.dataset.action;if(sharedAction(a,el,state,{render,transition,toast}))return;if(salaryAction(a,el,state,{render,transition,copy,toast,root:app}))return;if(personalAction(a,el,state,{render,transition}))return;if(['unavailable','search','attach','skills','new-chat','more','print','share','report-error','inspect-computer','categories-filter','dates'].includes(a)||a.startsWith('chart-')||a.startsWith('period-')){toast('Это действие недоступно в прототипе');return;}
if(a==='choose-problem'||a==='new-chat'){chooseTask();return;}if(a==='open-chat'){openChat();return;}if(a==='resume-chat'){state.page='chat';state.minimized=false;state.mode=state.returnMode==='choose'?'choose':'chat';render();return;}if(a==='back'){minimizeChat();return;}if(a==='finish'){finish();return;}
if(a==='date-edit'){state.dateEditing=el.dataset.field;render();return;}if(a==='date-day'){const d=el.dataset.date;if(state.dateEditing==='from'){state.dateFrom=d;if(d>state.dateTo)state.dateTo=d;state.dateEditing='to';}else{state.dateTo=d;if(d<state.dateFrom)state.dateFrom=d;}render();return;}if(a==='date-month'){const m=el.dataset.month.padStart(2,'0');state.dateFrom=`2025-${m}-01`;state.dateTo=`2025-${m}-${m==='10'?'31':'30'}`;render();return;}if(a==='calendar-done'&&state.reportDateEditing){state.reportDateEditing=false;state.reportPeriod='custom';state.rangeApplied=true;state.period=new Date(state.dateFrom+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'})+' — '+new Date(state.dateTo+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});transition('computer-result','Показать за выбранные даты');return;}if(a==='calendar-done'){state.rangeApplied=true;state.period=state.dateFrom==='2025-09-01'&&state.dateTo==='2025-11-30'?'Сентябрь — ноябрь':state.dateFrom==='2025-11-01'&&state.dateTo==='2025-11-30'?'Ноябрь':new Date(state.dateFrom+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'})+' — '+new Date(state.dateTo+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});state.overlay=null;touch();render();return;}
if(a==='computer-november'){state.reportPeriod='Ноябрь';transition('computer-result',el.textContent.trim());return;}if(a==='report-dates'){state.overlay='dates';state.reportDateEditing=true;state.dateFrom='2025-11-01';state.dateTo='2025-11-30';render();return;}if(a==='filter-category'){state.category=el.dataset.value;state.overlay=null;touch();render();return;}if(a==='bank-back'){state.page='overview';render();return;}if(a==='home-operations'){state.page='overview';render();return;}if(a==='open-expenses'||a==='open-income'){state.income=a==='open-income';startReveal();return;}if(['dates','search','more','expected','report-error','categories-filter'].includes(a)){state.overlay=a;render();return;}if(a==='inspect-computer'){state.overlay='inspect';render();return;}if(a==='close-sheet'){state.overlay=null;state.reportDateEditing=false;render();return;}if(a==='dismiss'){dismissTaya();return;}if(a.startsWith('chart-')){state.chart=a.slice(6);state.chartAnimate=true;touch();render();return;}if(a.startsWith('period-')){state.rangeApplied=false;state.period=a==='period-Год'?'Сентябрь — ноябрь':'Ноябрь';state.chartAnimate=false;touch();render();return;}
if(a==='toggle-refund'||a==='toggle-salary'){const set=a==='toggle-refund'?state.selectedRefunds:state.selectedSalary;set.has(el.dataset.id)?set.delete(el.dataset.id):set.add(el.dataset.id);render();return;}if(a==='save-expected'){const n=Number($('#expected-input').value);if(!Number.isFinite(n)||n<=0||n>10000000){toast('Введите сумму от 1 до 10 000 000');return;}state.expected=n;state.expectedSet=true;transition('salary-select','За ноябрь по расчётному листку должно прийти '+money(n));return;}if(a==='computer-rules'){state.overlay='rules';render();return;}if(a==='toggle-computer'){state.exclude=!state.exclude;render();return;}if(a==='save-rules'){transition('computer-result','Показать результат с выбранными правилами');return;}if(a==='edit-report'){if(state.scenario==='computer'){state.overlay='rules';render();}else transition(state.scenario==='salary'?'salary-select':'friends-select');return;}
if(a==='copy'||a==='copy-draft'){const article=el.closest('.chat-turn')?.querySelector('.answer')||app.querySelector('.chat-turn:last-child .answer');await copy(a==='copy-draft'?app.querySelector('.chat-turn:last-child .draft-message')?.innerText||article.innerText:article.innerText);return;}if(a==='like'||a==='dislike'){const id=el.closest('[data-message]')?.dataset.message;state.feedback[id]=state.feedback[id]===a?null:a;render();return;}if(a==='print'){state.overlay=null;render();const current=app.querySelector('.chat-turn:last-child .answer');$('#print-report').innerHTML='<h1>Тая — персональная аналитика</h1><p>Демонстрационный отчёт. Все данные вымышлены.</p>'+current.innerHTML;window.print();return;}if(a==='share'){await copy(app.querySelector('.chat-turn:last-child .answer').innerText+'\n\n'+location.href);return;}if(a==='save-error'){state.overlay=null;render();toast('Отзыв отмечен в демонстрации');return;}if(a==='attach'||a==='skills'){toast(a==='attach'?'В демо используются готовые операции':'Персональная аналитика');return;}
if(a==='pick-bill'||a==='pick-purchase'){state.overlay=a;render();return;}if(a==='select-demo-operation'){transition(state.scenario==='friends'?'friends-select':'computer-period',state.scenario==='friends'?'Этот счёт':'Да, исключить из расчёта');return;}if(a.startsWith('friends-')||a.startsWith('computer-')||a.startsWith('salary-')){if(a==='salary-result'&&!state.selectedSalary.size){toast('Выберите хотя бы одну выплату');return;}state.scenario=a.split('-')[0];transition(a,el.textContent.trim());return;}});
document.querySelectorAll('#scenario-picker [data-scenario]').forEach(el=>el.addEventListener('click',()=>{if(state.mode==='choose')playRequest(el.dataset.scenario);}));
if(document.body)bindShortWords(document.body);
$('#write-reimbursement').addEventListener('click',playReimbursement);
$('#start-demo').addEventListener('click',prepareIntro);$('#play-intro').addEventListener('click',startIntro);$('#reset-demo').addEventListener('click',prepareIntro);$('#restart-all').addEventListener('click',prepareIntro);$('#other-task').addEventListener('click',chooseTask);$('#finish-task').addEventListener('click',finish);$('#close-prototype').addEventListener('click',()=>{playback?.destroy();typingGeneration++;reset();$('#prototype').hidden=true;$('#landing').hidden=false;$('#start-demo').focus();});$('#choose-another').addEventListener('click',chooseTask);$('#toggle-playback').addEventListener('click',()=>{if(state.mode==='await-taya'){startIntro();return;}if(playback?.running)playback.pause();else playback?.play();updateStage();});
let visibilityPaused=false;document.addEventListener('visibilitychange',()=>{if(document.hidden&&playback?.running){visibilityPaused=true;playback.pause();}else if(!document.hidden&&visibilityPaused){visibilityPaused=false;playback?.play();}updateStage();});reset();
